() => {
  // Get all prices from the page
  const prices = [];
  document.querySelectorAll('*').forEach(el => {
    if (el.children.length === 0 && el.textContent && el.textContent.match(/^\$[\d,]+\.\d{2}$/)) {
      prices.push(el.textContent.trim());
    }
  });
  // Get configuration details
  const configs = [];
  document.querySelectorAll('fieldset, [class*="config"]').forEach(el => {
    const text = el.textContent.trim();
    if (text.length < 1000) configs.push(text);
  });
  return {prices: prices.slice(0, 20), configs: configs.slice(0, 5)};
}

() => {
  // Look for M3 Max prices and configurations on this page
  const results = {allPrices: [], configs: [], m3MaxInfo: ''};

  // Get all visible price-like strings
  document.querySelectorAll('span, div').forEach(el => {
    if (el.children.length === 0 && el.textContent && el.textContent.match(/^\$[\d,]+\.\d{2}$/)) {
      results.allPrices.push(el.textContent.trim());
    }
  });

  // Get configuration text
  document.querySelectorAll('fieldset, [class*="model"]').forEach(el => {
    const text = el.textContent.trim().substring(0, 500);
    if (text.includes('CPU') && text.includes('Memory')) {
      results.configs.push(text);
    }
  });

  // Get page text snippets mentioning M3 Max
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const texts = [];
  let node;
  while (node = walker.nextNode()) {
    if (node.nodeValue && (node.nodeValue.includes('M3 Max') || node.nodeValue.includes('CPU') || node.nodeValue.includes('GPU'))) {
      const parent = node.parentElement;
      if (parent && parent.children.length <= 1) {
        texts.push(node.nodeValue.trim());
      }
    }
  }
  results.m3MaxInfo = texts.slice(0, 30).join(' | ');
  return results;
}

() => {
  // Get all visible text on the page that has prices
  const allElements = Array.from(document.querySelectorAll('span, div, button'));
  const priceItems = [];
  for (const el of allElements) {
    const text = el.innerText || '';
    if (text.match(/^\$[\d,]+\.\d{2}/) && el.children.length === 0) {
      // Get the parent context
      let parent = el.parentElement;
      while (parent && parent.innerText.length > 1000) parent = parent.parentElement;
      const context = parent ? parent.innerText : text;
      priceItems.push({price: text.trim(), contextSnippet: context.substring(0, 400)});
    }
  }
  return priceItems;
}
